contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address newOperator) public {
        require(caller != address(0), "caller must be nonzero");

        bool setOperatorReverted;
        if (caller != address(this)) {
            try c.setOperator(newOperator) {
                setOperatorReverted = false;
            } catch {
                setOperatorReverted = true;
            }
        }

        bool setRewardsRecipientReverted;
        if (caller != address(this)) {
            try c.setRewardsRecipient(newOperator) {
                setRewardsRecipientReverted = false;
            } catch {
                setRewardsRecipientReverted = true;
            }
        }

        bool recoverTokenReverted;
        if (caller != address(this)) {
            try c.recoverToken(address(c), newOperator, 0) {
                recoverTokenReverted = false;
            } catch {
                recoverTokenReverted = true;
            }
        }

        bool withdrawAllAndUnwrapReverted;
        if (caller != address(this)) {
            try c.withdrawAllAndUnwrap(false, false) {
                withdrawAllAndUnwrapReverted = false;
            } catch {
                withdrawAllAndUnwrapReverted = true;
            }
        }

        bool setCvxPoolInfoReverted;
        if (caller != address(this)) {
            try c.setCvxPoolInfo(0, newOperator, newOperator) {
                setCvxPoolInfoReverted = false;
            } catch {
                setCvxPoolInfoReverted = true;
            }
        }

        bool nonOwnerAllReverted = true;
        if (caller != address(this)) {
            nonOwnerAllReverted =
                setOperatorReverted &&
                setRewardsRecipientReverted &&
                recoverTokenReverted &&
                withdrawAllAndUnwrapReverted &&
                setCvxPoolInfoReverted;
        }

        bool ownerNoRevert = true;
        if (caller == address(this)) {
            ownerNoRevert = !setOperatorReverted &&
                !setRewardsRecipientReverted &&
                !recoverTokenReverted &&
                !withdrawAllAndUnwrapReverted &&
                !setCvxPoolInfoReverted;
        }

        assert(
            (caller == address(this) && ownerNoRevert) ||
            (caller != address(this) && nonOwnerAllReverted)
        );
    }
}

