contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, bool claim) public {
        require(amount > 0, "amount must be positive");
        clpToken.transfer(address(c), amount);
        uint256 clpBefore = clpToken.balanceOf(address(c));
        require(amount <= clpBefore, "amount exceeds C's clpToken balance");

        uint256 ethBefore = address(c).balance;

        bool reverted;
        try c.withdrawAndUnwrap(amount, claim, address(c)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(!reverted && clpToken.balanceOf(address(c)) == clpBefore && address(c).balance == ethBefore);
    }

    IERC20 private clpToken;

    // The clpToken address is fetched from C's public immutable getter in the constructor
    // but the test contract can't store it in a field easily without modifying signature.
    // We use a helper view via c.clpToken(), but that's a view call on c, allowed.
    // However, we need to call transfer on the token, so we need the token instance.

    // To keep the required shape, we'll instead set up the token balance by calling a function on c that transfers to c,
    // but C has no such function. Therefore we must transfer tokens directly to c using the token contract.
    // Since we can't declare extra contracts, we'll use the IERC20 interface already defined in the unit.
    // But we need an instance of the token. We can get it from c.clpToken() and cast it to IERC20.
    // Casting is allowed for non-state-changing calls? The rule says no alias, cast, or interface for state-changing calls on c.
    // For token.transfer it's a call on the token, not on c. That's allowed.
    // But we need the token address from c.clpToken(), which is a view call on c.
    // Then we cast to IERC20 and call transfer. That's fine.

    // However, the test contract cannot hold the token instance as a state variable because it depends on c.
    // We'll just do it inline in run().

    // Rewriting run to fetch token and transfer:
    // But we need to keep the exact shape: every state-changing call on c is top-level.

    // Let's rewrite:

    function run(uint256 amount, bool claim) public {
        require(amount > 0, "amount must be positive");
        IERC20 token = c.clpToken();
        token.transfer(address(c), amount);
        uint256 clpBefore = token.balanceOf(address(c));
        require(amount <= clpBefore, "amount exceeds C's clpToken balance");

        uint256 ethBefore = address(c).balance;

        bool reverted;
        try c.withdrawAndUnwrap(amount, claim, address(c)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(!reverted && token.balanceOf(address(c)) == clpBefore && address(c).balance == ethBefore);
    }

    receive() external payable {}
}

