contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, uint32 pid, address token, address rewards, address newOperator, address recipient) public payable {
        // Record old values through public getters
        address oldOperator = c.operator();
        address oldRecipient = c.rewardsRecipient();
        uint32 oldPid = c.cvxPoolInfo().pId;
        address oldPoolToken = c.cvxPoolInfo().token;
        address oldPoolRewards = c.cvxPoolInfo().rewards;

        // Call state setters only when allowed by ownership; if not owner, the call must revert.
        bool setPoolReverted;
        try c.setCvxPoolInfo(pid, token, rewards) {
            setPoolReverted = false;
        } catch {
            setPoolReverted = true;
        }

        bool setOperatorReverted;
        try c.setOperator(newOperator) {
            setOperatorReverted = false;
        } catch {
            setOperatorReverted = true;
        }

        bool setRecipientReverted;
        try c.setRewardsRecipient(recipient) {
            setRecipientReverted = false;
        } catch {
            setRecipientReverted = true;
        }

        // Read final public values
        address newOperatorAfter = c.operator();
        address newRecipientAfter = c.rewardsRecipient();
        uint32 newPidAfter = c.cvxPoolInfo().pId;
        address newPoolTokenAfter = c.cvxPoolInfo().token;
        address newPoolRewardsAfter = c.cvxPoolInfo().rewards;

        bool isOwner = msg.sender == c.owner();

        // Rule: setters either revert when not owner, or their public state effect is exactly the assigned value.
        // If the call did not revert and sender is not owner, then it must have reverted according to the contract's onlyOwner semantics.
        // Since onlyOwner reverts if not owner, we expect setPoolReverted == !isOwner etc.
        bool poolEffectCorrect = setPoolReverted
            ? (newPidAfter == oldPid && newPoolTokenAfter == oldPoolToken && newPoolRewardsAfter == oldPoolRewards)
            : (newPidAfter == pid && newPoolTokenAfter == token && newPoolRewardsAfter == rewards);

        bool operatorEffectCorrect = setOperatorReverted
            ? (newOperatorAfter == oldOperator)
            : (newOperatorAfter == newOperator);

        bool recipientEffectCorrect = setRecipientReverted
            ? (newRecipientAfter == oldRecipient)
            : (newRecipientAfter == recipient);

        // Also, if sender is not owner, each setter must revert; if sender is owner, they must not revert.
        bool revertCorrect = isOwner
            ? (!setPoolReverted && !setOperatorReverted && !setRecipientReverted)
            : (setPoolReverted && setOperatorReverted && setRecipientReverted);

        // The operator-only depositAndStake should revert unless the caller is the current operator.
        bool depositReverted;
        try c.depositAndStake(amount) {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        // After the setters, the current operator is newOperatorAfter. msg.sender is this contract.
        // So depositAndStake should succeed iff msg.sender == newOperatorAfter.
        bool depositCorrect = depositReverted ? (msg.sender != newOperatorAfter) : (msg.sender == newOperatorAfter);

        assert(poolEffectCorrect && operatorEffectCorrect && recipientEffectCorrect && revertCorrect && depositCorrect);
    }

    receive() external payable {}
}

