        bool ownerChanged;
        bool ownerCallReverted;

        // Owner path: this contract is the owner because it deployed c.
        try c.setOperator(newOperator) {
            ownerCallReverted = false;
            ownerChanged = (c.operator() == newOperator);
        } catch {
            ownerCallReverted = true;
            ownerChanged = false;
        }

        // Non-owner path: attacker cannot change the operator.
        bool attackerCallReverted;
        bool attackerChangedOperator;
        try c.setOperator(attacker) {
            attackerCallReverted = false;
            attackerChangedOperator = (c.operator() != newOperator);
        } catch {
            attackerCallReverted = true;
            attackerChangedOperator = (c.operator() != newOperator);
        }

        assert(
            ownerCallReverted == false &&
            ownerChanged &&
            attackerCallReverted &&
            !attackerChangedOperator &&
            c.operator() == newOperator
        );

        // restore the initial operator so that this test is self-contained
        c.setOperator(operatorBefore);
    }

    receive() external payable {}
}

