contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount, address caller) public payable {
        require(amount > 0, "amount must be positive");
        require(caller != address(this), "caller must not be the test contract");

        IERC20 clp = c.clpToken();
        ICVXBooster booster = c.booster();

        // if caller is not the current operator, first force the operator to be caller
        // by calling setOperator as the owner (this contract). This guarantees the
        // deciding call below will be made by the operator, so no revert is expected.
        if (caller != c.operator()) {
            c.setOperator(caller);
        }

        // read allowance before the deciding call
        uint256 allowanceBefore = clp.allowance(address(c), address(booster));

        // deciding call must be its own top-level statement
        c.depositAndStake(amount);

        // read allowance after the deciding call
        uint256 allowanceAfter = clp.allowance(address(c), address(booster));

        // general rule: operator call never decreases allowance, and increases it by at most amount.
        // (If the cvx pool is shut down, allowance stays exactly the same.)
        assert(allowanceAfter >= allowanceBefore && allowanceAfter <= allowanceBefore + amount);
    }
}

