contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient, address rewardToken, bool claimExtras) public {
        // Safely configure the rewardsRecipient to a non-zero address for the rule.
        if (recipient == address(0)) {
            recipient = address(1);
        }
        c.setRewardsRecipient(recipient);

        // Set a single reward token so the balance-change rule is well-defined.
        // rewardTokens is a public dynamic array; we cannot push, but we can
        // observe the existing first token. If none exists, the rule is not
        // applicable, so we skip the balance assertion by keeping before == after.
        // We only need at least one token for a meaningful rule.

        // Read before balances.
        uint256 beforeRecipient = 0;
        uint256 beforeC = 0;
        bool hasRewardToken = false;
        address firstRewardToken = address(0);
        // rewardTokens is public, so the getter c.rewardTokens(uint) exists.
        // We cannot know the length without another function, but trying index 0
        // in a try/catch isn't allowed inside assert/require. Since we can't
        // call a non-existent getter without reverting, we only proceed if the
        // test receives a concrete rewardToken address; use that token for
        // observations. The contract will transfer *all* rewardTokens it has,
        // but the specific token may or may not be one of them. To keep the
        // rule precise, we require the rewardToken parameter to be the first
        // token in c.rewardTokens by checking equality with a call that would
        // revert if index 0 doesn't exist. Since view calls can go inside
        // require, we can attempt c.rewardTokens(0) and catch reverts only via
        // a separate try/catch, which is not allowed here. So instead we simply
        // assume the caller supplies the token that c actually holds rewards in.
        // The assertion will fail if the setup is wrong, but property tests
        // typically allow choosing parameters that make the property applicable.

        // To keep this general yet compilable, observe the given rewardToken.
        firstRewardToken = rewardToken;
        hasRewardToken = (firstRewardToken != address(0));
        if (hasRewardToken) {
            beforeRecipient = IERC20(firstRewardToken).balanceOf(recipient);
            beforeC = IERC20(firstRewardToken).balanceOf(address(c));
        }

        // Perform the reward claim.
        c.getReward(claimExtras);

        // Read after balances.
        uint256 afterRecipient = 0;
        uint256 afterC = 0;
        if (hasRewardToken) {
            afterRecipient = IERC20(firstRewardToken).balanceOf(recipient);
            afterC = IERC20(firstRewardToken).balanceOf(address(c));
        }

        // General rule: if a non-zero rewardsRecipient is set, then after
        // getReward, the recipient balance of the observed reward token
        // increases by exactly the amount that was held by c before
        // (c's balance drops to zero for that token).
        // This holds for any reward token that c actually distributes.
        if (hasRewardToken && recipient != address(0)) {
            assert(afterRecipient == beforeRecipient + beforeC);
            assert(afterC == 0);
        } else {
            assert(afterRecipient == beforeRecipient);
        }
    }

    receive() external payable {}
}

