contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address newOperator) public payable {
        require(caller != address(0));
        require(newOperator != address(0));

        address owner = c.owner();
        address oldOperator = c.operator();

        bool reverted;
        if (caller == owner) {
            // Owner path: setOperator must succeed and update operator.
            c.setOperator(newOperator);
            reverted = false;
        } else {
            // Non-owner path: setOperator must revert and operator must stay unchanged.
            try c.setOperator(newOperator) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        address finalOperator = c.operator();

        // General rule: caller authority matches success/failure, and operator update is atomic.
        if (caller == owner) {
            assert(!reverted && finalOperator == newOperator);
        } else {
            assert(reverted && finalOperator == oldOperator);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address newOperator) public payable {
        require(newOperator != address(0));
        address ownerBefore = c.owner();
        address operatorBefore = c.operator();
        bool reverted = true;
        (bool success, ) = address(c).call(abi.encodeWithSelector(C.setOperator.selector, newOperator));
        reverted = !success;
        address operatorAfter = c.operator();
        assert(
            (caller == ownerBefore && !reverted && operatorAfter == newOperator) ||
            (caller != ownerBefore && reverted && operatorAfter == operatorBefore)
        );
    }

    receive() external payable {}
}

