contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 depositAmount, uint256 withdrawAmount, address to) public payable {
        require(to != address(0), "to must not be zero");
        require(address(this).balance >= depositAmount, "insufficient balance pre-donation");
        if (withdrawAmount > 0) {
            require(address(this).balance >= withdrawAmount, "insufficient balance for transfer");
        }

        // Read the operator that was set at deployment; the test contract is the deployer and owner.
        address op = c.operator();

        // Ensure the test contract is the operator so that depositAndStake is callable.
        if (op != address(this)) {
            c.setOperator(address(this));
        }

        // Read the CLP token and fund this contract with enough tokens for the deposit.
        IERC20 clp = c.clpToken();
        if (depositAmount > 0) {
            (bool funded) = address(clp).call(abi.encodeWithSignature("transfer(address,uint256)", address(this), depositAmount));
            require(funded, "funding call failed");
        }

        // Approve the contract to pull the deposit amount from this test contract.
        clp.approve(address(c), depositAmount);

        // Set up the CVX pool info so that isCvxShutdown() reads a valid pool.
        // Use a zero-address rewards pool; the contract will skip actual unwinding.
        c.setCvxPoolInfo(0, address(clp), address(0));

        // Record the recipient's CLP balance before the operation.
        uint256 toBalanceBefore = clp.balanceOf(to);

        // Perform the deposit and then the withdraw. These are state-changing top-level calls.
        c.depositAndStake(depositAmount);

        bool withdrawReverted;
        try c.withdrawAndUnwrap(withdrawAmount, false, to) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // The recipient must receive exactly withdrawAmount CLP tokens.
        uint256 toBalanceAfter = clp.balanceOf(to);

        assert(
            !withdrawReverted &&
            toBalanceAfter == toBalanceBefore + withdrawAmount
        );
    }

    receive() external payable {}
}

